// Phase vocoder: Pitch, time and wet mix. FFT order is prepared from source, not changed in the audio callback.
// Audition composition of public Rust primitives; not an instrument parity claim.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  phaseVocoder as phaseVocoderDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    phaseVocoder_mode: {
      "path": "/primitives/phase-vocoder/node/0",
      "label": "Mode",
      "group": "Phase vocoder",
      "min": 0,
      "max": 1,
      "default": 0,
      "choices": [
        "Bin mapping",
        "Stretch then resample"
      ]
    },
    phaseVocoder_pitchSemitones: {
      "path": "/primitives/phase-vocoder/node/1",
      "label": "Pitch semitones",
      "group": "Phase vocoder",
      "min": -24,
      "max": 24,
      "default": 7
    },
    phaseVocoder_timeStretch: {
      "path": "/primitives/phase-vocoder/node/2",
      "label": "Time stretch",
      "group": "Phase vocoder",
      "min": 0.25,
      "max": 4,
      "default": 1
    },
    phaseVocoder_wetMix: {
      "path": "/primitives/phase-vocoder/node/3",
      "label": "Wet mix",
      "group": "Phase vocoder",
      "min": 0,
      "max": 1,
      "default": 1
    },
  };

  // Audio inputs and outputs — the host supplies the external audio input.
  const graph = createGraphWorkspace().setInputSource('external');
  const input = graph.input.output('out');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const phaseVocoder = graph.add(phaseVocoderDefinition.type, {"id":4});
  graph.registerInstance('/primitives/phase-vocoder/node', phaseVocoder);
  phaseVocoder.parameter('mode').expose(controls.phaseVocoder_mode);
  phaseVocoder.parameter('pitchSemitones').expose(controls.phaseVocoder_pitchSemitones);
  phaseVocoder.parameter('timeStretch').expose(controls.phaseVocoder_timeStretch);
  phaseVocoder.parameter('wetMix').expose(controls.phaseVocoder_wetMix);
  phaseVocoder.parameter('fftOrder').set(11);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(input, phaseVocoder.input('audio'));
  graph.connect(phaseVocoder.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.phaseVocoder_mode,
    controls.phaseVocoder_pitchSemitones,
    controls.phaseVocoder_timeStretch,
    controls.phaseVocoder_wetMix
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
